// Deja el fallo visible: se registra con los datos necesarios para investigarlo.
// En producción, aquí se enviaría una alerta (Slack, email, PagerDuty...).
const d = $input.first().json;
const report = {
  workflow: d.workflow && d.workflow.name,
  executionId: d.execution && d.execution.id,
  executionUrl: d.execution && d.execution.url,
  failedNode: d.execution && d.execution.lastNodeExecuted,
  error: d.execution && d.execution.error && d.execution.error.message,
  at: new Date().toISOString(),
};
console.error('[LendLoop automation failed]', JSON.stringify(report));
return [{ json: report }];
